"""Ordered notification log (C32).

Notifications are tuples: the event type followed by its arguments, for example
("REORDER", "BOLT", "A") or ("OVERDRAWN",). The log is part of the Depot state, so
it is snapshotted and restored together with everything else on undo and on
failed operations.
"""


class EventLog:
    def __init__(self, items=()):
        self._items = [tuple(i) for i in items]

    def emit(self, *event):
        self._items.append(tuple(event))

    def items(self):
        return list(self._items)
