"""Money arithmetic. All amounts are integer cents; rounding uses the depot's decimal mode.

Pure functions only. Nothing here chooses a late-penalty percentage: that value
is supplied by the caller and is still owed by the owner (C18).
"""
import decimal
from decimal import Decimal

# The decimal module's rounding constants are strings such as "ROUND_HALF_EVEN".
ROUNDING_MODES = frozenset(
    getattr(decimal, name) for name in dir(decimal) if name.startswith("ROUND_")
)


def _cents(amount, mode):
    """Round a Decimal amount to a whole cent using a decimal rounding mode."""
    return int(amount.quantize(Decimal(1), rounding=mode))


def list_price(unit_cost, markup, mode):
    """C08: unit_cost × (1 + markup), rounded to a whole cent."""
    factor = Decimal(1) + Decimal(str(markup))
    return _cents(Decimal(unit_cost) * factor, mode)


def sale_total(price, qty, bulk_threshold, bulk_discount_pct, mode):
    """C07 + C09: price × qty, with the bulk discount when qty >= bulk_threshold."""
    gross = price * qty
    if qty >= bulk_threshold:
        pct = Decimal(str(bulk_discount_pct))
        return _cents(Decimal(gross) * (Decimal(100) - pct) / Decimal(100), mode)
    return gross


def late_adjusted(cost, penalty_pct, mode):
    """C18 mechanism: a late delivery costs the penalty percentage less."""
    pct = Decimal(str(penalty_pct))
    return _cents(Decimal(cost) * (Decimal(100) - pct) / Decimal(100), mode)


def storage_charge(units, cents_per_unit_day):
    """C19: storage for every unit held for one day."""
    return units * cents_per_unit_day


def transfer_cost(qty, cents_per_unit):
    """C11: the sending side pays per unit transferred."""
    return qty * cents_per_unit


def turnover(units_shipped, average_units):
    """C30: units shipped / average units held; None when the average is 0."""
    if average_units == 0:
        return None
    return float(units_shipped / average_units)
