"""Supplier reliability and purchase orders (C15, C16, C17).

Pure state holder. The Depot performs argument validation and emits notifications;
this module only tracks reliability values and orders.
"""

START_RELIABILITY = 3
MIN_RELIABILITY = 0
MAX_RELIABILITY = 5
SUSPEND_AT = 1          # reliability <= 1 means suspended
REINSTATE_TO = 2


class Suppliers:
    def __init__(self):
        self.rel = {}      # name -> reliability
        self.orders = {}   # order id -> dict
        self.next_id = 1

    def exists(self, name):
        return name in self.rel

    def ensure(self, name):
        self.rel.setdefault(name, START_RELIABILITY)

    def reliability(self, name):
        return self.rel.get(name)

    def is_suspended(self, name):
        r = self.rel.get(name)
        return r is not None and r <= SUSPEND_AT

    def rate(self, name, on_time):
        """Apply one delivery outcome. Returns True if the supplier just became suspended."""
        before = self.rel[name]
        if on_time:
            after = min(MAX_RELIABILITY, before + 1)
        else:
            after = max(MIN_RELIABILITY, before - 1)
        self.rel[name] = after
        return before > SUSPEND_AT and after <= SUSPEND_AT

    def reinstate(self, name):
        self.rel[name] = REINSTATE_TO

    def add_order(self, supplier, sku, qty, due_day, wh):
        oid = self.next_id
        self.next_id += 1
        self.orders[oid] = {
            "supplier": supplier,
            "sku": sku,
            "qty": qty,
            "due_day": due_day,
            "wh": wh,
            "status": "open",
        }
        return oid

    def order(self, oid):
        return self.orders.get(oid)

    def close(self, oid, status):
        self.orders[oid]["status"] = status
