"""Depot: a small multi-warehouse inventory and cash ledger.

Every mutating operation is atomic: on any DepotError the whole state is restored
from a snapshot taken before the operation. On success the pre-operation snapshot
becomes the undo record (C27), except advance_day, which blocks undo.
"""
import copy
import functools
import json
import tomllib
from fractions import Fraction
from pathlib import Path

import events
import money
import suppliers as supmod

_DATA_PATH = Path(__file__).with_name("data.toml")
_BLOCKED = "BLOCKED"
_STATE_FIELDS = (
    "_items", "_lots", "_cash", "_day", "_armed", "_held",
    "_shipped", "_returned", "_log", "_sup",
)


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _load_defaults():
    with open(_DATA_PATH, "rb") as f:
        return tomllib.load(f)


def _mutating(blocks_undo=False):
    """Make an operation atomic and record its undo snapshot on success."""
    def decorate(fn):
        @functools.wraps(fn)
        def wrapper(self, *args, **kwargs):
            snap = self._capture()
            try:
                result = fn(self, *args, **kwargs)
            except BaseException:
                self._restore(snap)
                raise
            self._undo = _BLOCKED if blocks_undo else snap
            return result
        return wrapper
    return decorate


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode, *,
                 markup=None, bulk_threshold=None, bulk_discount_pct=None,
                 storage_cents_per_unit_day=None, transfer_cents_per_unit=None,
                 late_penalty_pct=None):
        names = list(warehouses) if isinstance(warehouses, (list, tuple)) else []
        if not names or len(set(names)) != len(names) or not all(
                isinstance(n, str) and n for n in names):
            raise DepotError("INVALID_ARG")
        if not isinstance(capacities, dict) or set(capacities) != set(names):
            raise DepotError("INVALID_ARG")
        if not all(_is_int(c) and c >= 0 for c in capacities.values()):
            raise DepotError("INVALID_ARG")
        if not _is_int(opening_cash):
            raise DepotError("INVALID_ARG")
        if rounding_mode not in money.ROUNDING_MODES:
            raise DepotError("INVALID_ARG")
        if late_penalty_pct is not None and not (
                isinstance(late_penalty_pct, (int, float))
                and not isinstance(late_penalty_pct, bool)
                and 0 <= late_penalty_pct <= 100):
            raise DepotError("INVALID_ARG")

        needs_file = None in (markup, bulk_threshold, bulk_discount_pct,
                              storage_cents_per_unit_day, transfer_cents_per_unit)
        data = _load_defaults() if needs_file else {}
        self._cfg = {
            "markup": markup if markup is not None else data["markup"],
            "bulk_threshold": bulk_threshold if bulk_threshold is not None else data["bulk_threshold"],
            "bulk_discount_pct": bulk_discount_pct if bulk_discount_pct is not None else data["bulk_discount_pct"],
            "storage": storage_cents_per_unit_day if storage_cents_per_unit_day is not None else data["storage_cents_per_unit_day"],
            "transfer": transfer_cents_per_unit if transfer_cents_per_unit is not None else data["transfer_credit_cents_per_unit"],
            "late_penalty_pct": late_penalty_pct,   # None = not yet decided by owner (C18)
            "mode": rounding_mode,
        }

        self._warehouses = names
        self._capacities = dict(capacities)
        self._items = {}
        self._lots = {}          # (sku, wh) -> list of [day_received, qty], FIFO
        self._cash = opening_cash
        self._day = 0
        self._armed = {}         # (sku, wh) -> bool, for C14
        self._held = {}          # day -> units held during that day (storage basis)
        self._shipped = []       # (day, sku, wh, qty)
        self._returned = {}      # sku -> units returned
        self._log = events.EventLog()
        self._sup = supmod.Suppliers()
        self._undo = None

    # ------------------------------------------------------------------ properties
    @property
    def cash(self):
        return self._cash

    @property
    def day(self):
        return self._day

    def notifications(self):
        return self._log.items()

    # ------------------------------------------------------------------ validation
    def _check_sku(self, sku):
        if not isinstance(sku, str) or sku not in self._items:
            raise DepotError("UNKNOWN_SKU")

    def _check_wh(self, wh):
        if not isinstance(wh, str) or wh not in self._capacities:
            raise DepotError("UNKNOWN_WAREHOUSE")

    @staticmethod
    def _check_qty(qty):
        if not _is_int(qty) or qty <= 0:
            raise DepotError("INVALID_QTY")

    @staticmethod
    def _check_money(value):
        if not _is_int(value) or value < 0:
            raise DepotError("INVALID_ARG")

    @staticmethod
    def _check_supplier(name):
        if not isinstance(name, str) or not name:
            raise DepotError("INVALID_ARG")

    def _perishable(self, sku):
        shelf = self._items[sku]["shelf_life"]
        return shelf is not None and shelf >= 1

    # ------------------------------------------------------------------ lot helpers
    def _stock(self, sku, wh):
        return sum(q for _, q in self._lots.get((sku, wh), ()))

    def _wh_units(self, wh):
        return sum(q for (_, w), lots in self._lots.items() if w == wh for _, q in lots)

    def _total_units(self):
        return sum(q for lots in self._lots.values() for _, q in lots)

    def _add_lot(self, sku, wh, day, qty):
        self._lots.setdefault((sku, wh), []).append([day, qty])

    def _take(self, sku, wh, qty):
        """Remove qty units oldest-first. Caller guarantees enough stock. Returns (day, taken) pieces."""
        lots = self._lots[(sku, wh)]
        lots.sort(key=lambda lot: lot[0])
        taken = []
        need = qty
        while need > 0:
            lot = lots[0]
            t = min(lot[1], need)
            taken.append((lot[0], t))
            lot[1] -= t
            need -= t
            if lot[1] == 0:
                lots.pop(0)
        if not lots:
            del self._lots[(sku, wh)]
        return taken

    def _rearm(self):
        """C14: a stock level above the reorder level re-arms its REORDER notice."""
        for sku, item in self._items.items():
            for wh in self._warehouses:
                if self._stock(sku, wh) > item["reorder_level"]:
                    self._armed[(sku, wh)] = True

    def _receive_core(self, sku, qty, wh, cost):
        if self._cash < 0:
            raise DepotError("OVERDRAWN")                                  # C20
        if self._wh_units(wh) + qty > self._capacities[wh]:
            raise DepotError("CAPACITY")                                   # C04
        if self._cash - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")                         # C05
        self._cash -= cost
        self._add_lot(sku, wh, self._day, qty)

    def _receive_checked(self, sku, qty, wh):
        self._check_sku(sku)
        self._check_wh(wh)
        self._check_qty(qty)
        cost = self._items[sku]["unit_cost"] * qty
        self._receive_core(sku, qty, wh, cost)

    # ------------------------------------------------------------------ snapshot / undo
    def _capture(self):
        return {f: copy.deepcopy(getattr(self, f)) for f in _STATE_FIELDS}

    def _restore(self, state):
        for f in _STATE_FIELDS:
            setattr(self, f, state[f])

    @_mutating()
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        if not isinstance(sku, str) or not sku:
            raise DepotError("INVALID_ARG")
        if not _is_int(unit_cost) or unit_cost <= 0:
            raise DepotError("INVALID_ARG")
        if not _is_int(reorder_level) or reorder_level < 0:
            raise DepotError("INVALID_ARG")
        if shelf_life_days is not None and (not _is_int(shelf_life_days) or shelf_life_days < 0):
            raise DepotError("INVALID_ARG")
        if sku in self._items:
            raise DepotError("DUPLICATE_SKU")                              # C01
        self._items[sku] = {
            "unit_cost": unit_cost,
            "reorder_level": reorder_level,
            "shelf_life": shelf_life_days,
        }

    def list_price(self, sku):
        self._check_sku(sku)
        return money.list_price(self._items[sku]["unit_cost"], self._cfg["markup"], self._cfg["mode"])

    # ------------------------------------------------------------------ stock movements
    @_mutating()
    def receive(self, sku, qty, wh):
        self._receive_checked(sku, qty, wh)
        self._rearm()

    @_mutating()
    def receive_bulk(self, receipts):
        if not isinstance(receipts, (list, tuple)):
            raise DepotError("INVALID_ARG")
        for r in receipts:
            if not isinstance(r, (list, tuple)) or len(r) != 3:
                raise DepotError("INVALID_ARG")
            self._receive_checked(*r)
        self._rearm()

    @_mutating()
    def ship(self, sku, qty, wh, price):
        self._check_sku(sku)
        self._check_wh(wh)
        self._check_qty(qty)
        self._check_money(price)
        if self._stock(sku, wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")                         # C06
        c = self._cfg
        total = money.sale_total(price, qty, c["bulk_threshold"], c["bulk_discount_pct"], c["mode"])
        self._take(sku, wh, qty)
        self._cash += total                                                # C07, C09
        self._shipped.append((self._day, sku, wh, qty))
        key = (sku, wh)
        level = self._items[sku]["reorder_level"]
        if self._stock(sku, wh) <= level and self._armed.get(key, True):   # C14
            self._log.emit("REORDER", sku, wh)
            self._armed[key] = False

    @_mutating()
    def transfer(self, sku, qty, from_wh, to_wh):
        self._check_sku(sku)
        self._check_wh(from_wh)
        self._check_wh(to_wh)
        self._check_qty(qty)
        if from_wh == to_wh:
            raise DepotError("SAME_WAREHOUSE")
        if self._stock(sku, from_wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")                         # C10
        if self._wh_units(to_wh) + qty > self._capacities[to_wh]:
            raise DepotError("CAPACITY")                                   # C10
        cost = money.transfer_cost(qty, self._cfg["transfer"])             # C11
        for day, taken in self._take(sku, from_wh, qty):
            self._add_lot(sku, to_wh, day, taken)                          # keeps original age
        self._cash -= cost
        self._rearm()

    @_mutating()
    def return_goods(self, sku, qty, wh, price):
        self._check_sku(sku)
        self._check_wh(wh)
        self._check_qty(qty)
        self._check_money(price)
        shipped = sum(q for _, s, _, q in self._shipped if s == sku)
        if self._returned.get(sku, 0) + qty > shipped:
            raise DepotError("RETURN_EXCEEDS")                             # C23
        if self._perishable(sku):
            # C23: restock-or-discard for perishables is the owner's decision; not decided.
            raise DepotError("PERISHABLE_RETURN_UNDECIDED")
        if self._wh_units(wh) + qty > self._capacities[wh]:
            raise DepotError("CAPACITY")
        self._cash -= price * qty                                          # refund
        self._add_lot(sku, wh, self._day, qty)
        self._returned[sku] = self._returned.get(sku, 0) + qty
        self._rearm()

    # ------------------------------------------------------------------ day
    @_mutating(blocks_undo=True)
    def advance_day(self):
        # C21 order: storage charge, then expiry, then overdrawn check.
        units = self._total_units()
        self._cash -= money.storage_charge(units, self._cfg["storage"])    # C19
        self._held[self._day] = units
        for key in sorted(self._lots):
            sku, wh = key
            if not self._perishable(sku):
                continue
            keep, expired = [], 0
            for day, qty in self._lots[key]:
                if self._day - day > self._items[sku]["shelf_life"]:
                    expired += qty
                else:
                    keep.append([day, qty])
            if expired:
                self._log.emit("EXPIRY", sku, wh, expired)                 # C13
            if keep:
                self._lots[key] = keep
            else:
                del self._lots[key]
        if self._cash < 0:
            self._log.emit("OVERDRAWN")                                    # C20
        self._day += 1

    @_mutating()
    def undo_placeholder_never_called(self):  # pragma: no cover
        raise DepotError("INVALID_ARG")

    def undo(self):
        if self._undo is None:
            raise DepotError("NOTHING_TO_UNDO")
        if isinstance(self._undo, str):
            raise DepotError("UNDO_BLOCKED")                               # C27
        self._restore(self._undo)
        self._undo = None

    # ------------------------------------------------------------------ suppliers
    @_mutating()
    def place_order(self, supplier, sku, qty, due_day, wh=None):
        self._check_supplier(supplier)
        self._check_sku(sku)
        self._check_qty(qty)
        if not _is_int(due_day):
            raise DepotError("INVALID_ARG")
        if wh is None:
            if len(self._warehouses) != 1:
                raise DepotError("INVALID_ARG")
            wh = self._warehouses[0]
        self._check_wh(wh)
        if self._sup.is_suspended(supplier):
            raise DepotError("SUPPLIER_SUSPENDED")                         # C17
        self._sup.ensure(supplier)                                         # C15
        return self._sup.add_order(supplier, sku, qty, due_day, wh)        # C16

    @_mutating()
    def deliver(self, order_id, day):
        order = self._sup.order(order_id) if _is_int(order_id) else None
        if order is None:
            raise DepotError("UNKNOWN_ORDER")
        if order["status"] != "open":
            raise DepotError("ORDER_CLOSED")
        if not _is_int(day):
            raise DepotError("INVALID_ARG")
        late = day > order["due_day"]                                      # C16
        cost = self._items[order["sku"]]["unit_cost"] * order["qty"]
        if late:
            pct = self._cfg["late_penalty_pct"]
            if pct is None:
                # C18: the late-penalty percentage is undecided by the owner.
                raise DepotError("LATE_PENALTY_UNSET")
            cost = money.late_adjusted(cost, pct, self._cfg["mode"])
        self._receive_core(order["sku"], order["qty"], order["wh"], cost)
        self._rearm()
        self._sup.close(order_id, "late" if late else "on_time")
        if self._sup.rate(order["supplier"], on_time=not late):            # C15, C17
            self._log.emit("SUPPLIER_SUSPENDED", order["supplier"])

    def reliability(self, supplier):
        self._check_supplier(supplier)
        r = self._sup.reliability(supplier)
        if r is None:
            raise DepotError("UNKNOWN_SUPPLIER")
        return r

    @_mutating()
    def reinstate(self, supplier):
        self._check_supplier(supplier)
        if not self._sup.exists(supplier):
            raise DepotError("UNKNOWN_SUPPLIER")
        self._sup.reinstate(supplier)                                      # C17

    # ------------------------------------------------------------------ queries
    def stock(self, sku, wh=None):
        self._check_sku(sku)
        if wh is None:
            return sum(self._stock(sku, w) for w in self._warehouses)      # C25
        self._check_wh(wh)
        return self._stock(sku, wh)

    def report(self):
        rows = []
        for sku in sorted(self._items):
            unit_cost = self._items[sku]["unit_cost"]
            for wh in sorted(self._warehouses):
                units = self._stock(sku, wh)
                rows.append((sku, wh, units, units * unit_cost))           # C26
        return rows

    def turnover(self, start_day, end_day):
        if not (_is_int(start_day) and _is_int(end_day)) or start_day > end_day:
            raise DepotError("INVALID_ARG")
        shipped = sum(q for d, _, _, q in self._shipped if start_day <= d <= end_day)
        days = [d for d in self._held if start_day <= d <= end_day]
        if days:
            avg = Fraction(sum(self._held[d] for d in days), len(days))
        else:
            avg = Fraction(0)
        return money.turnover(shipped, avg)                                # C30

    # ------------------------------------------------------------------ audit
    @_mutating()
    def audit(self, counts):
        if not isinstance(counts, dict):
            raise DepotError("INVALID_ARG")
        if not counts:
            raise DepotError("EMPTY_AUDIT")                                # C22
        for key, counted in counts.items():
            if not (isinstance(key, tuple) and len(key) == 2):
                raise DepotError("INVALID_ARG")
            self._check_sku(key[0])
            self._check_wh(key[1])
            if not _is_int(counted) or counted < 0:
                raise DepotError("INVALID_ARG")
        for sku, wh in sorted(counts):
            ledger = self._stock(sku, wh)
            counted = counts[(sku, wh)]
            if ledger != counted:
                self._log.emit("AUDIT_MISMATCH", sku, wh, ledger, counted)

    # ------------------------------------------------------------------ save / load
    def save(self):
        data = {
            "version": 1,
            "warehouses": list(self._warehouses),
            "capacities": dict(self._capacities),
            "cash": self._cash,
            "day": self._day,
            "items": {
                sku: {
                    "unit_cost": v["unit_cost"],
                    "reorder_level": v["reorder_level"],
                    "shelf_life_days": v["shelf_life"],
                }
                for sku, v in self._items.items()
            },
            "lots": [[sku, wh, day, qty]
                     for (sku, wh) in sorted(self._lots)
                     for day, qty in self._lots[(sku, wh)]],
            "armed": [[sku, wh, flag] for (sku, wh), flag in sorted(self._armed.items())],
            "held": [[d, u] for d, u in sorted(self._held.items())],
            "shipped": [list(x) for x in self._shipped],
            "returned": dict(self._returned),
            "suppliers": {
                "rel": dict(self._sup.rel),
                "orders": [[oid, dict(o)] for oid, o in sorted(self._sup.orders.items())],
                "next_id": self._sup.next_id,
            },
            "notifications": [list(n) for n in self._log.items()],
        }
        return json.dumps(data, sort_keys=True)

    def _build_state(self, text):
        data = json.loads(text)
        if not isinstance(data, dict) or type(data.get("version")) is not int or data["version"] != 1:
            raise ValueError("version")
        if data["warehouses"] != self._warehouses or data["capacities"] != self._capacities:
            raise ValueError("warehouses/capacities are fixed at construction")

        items = {}
        for sku, v in data["items"].items():
            cost, level, shelf = v["unit_cost"], v["reorder_level"], v["shelf_life_days"]
            if not (_is_int(cost) and cost > 0 and _is_int(level) and level >= 0):
                raise ValueError("item")
            if shelf is not None and not (_is_int(shelf) and shelf >= 0):
                raise ValueError("shelf life")
            items[sku] = {"unit_cost": cost, "reorder_level": level, "shelf_life": shelf}

        cash = data["cash"]
        day = data["day"]
        if not _is_int(cash) or not _is_int(day) or day < 0:
            raise ValueError("cash/day")

        lots = {}
        for sku, wh, d, qty in data["lots"]:
            if sku not in items or wh not in self._capacities or not _is_int(d) or not _is_int(qty) or qty <= 0:
                raise ValueError("lot")
            lots.setdefault((sku, wh), []).append([d, qty])

        armed = {}
        for sku, wh, flag in data["armed"]:
            if sku not in items or wh not in self._capacities or not isinstance(flag, bool):
                raise ValueError("armed")
            armed[(sku, wh)] = flag

        held = {}
        for d, u in data["held"]:
            if not (_is_int(d) and _is_int(u)):
                raise ValueError("held")
            held[d] = u

        shipped = []
        for d, sku, wh, qty in data["shipped"]:
