        for name, r in sd["rel"].items():
            if not isinstance(name, str) or not _is_int(r) or not (0 <= r <= 5):
                raise ValueError("reliability")
            sup.rel[name] = r
        for oid, o in sd["orders"]:
            if not _is_int(oid) or not isinstance(o, dict) or o.get("sku") not in items:
