        sup.next_id = sd["next_id"]

        notes = []
        for n in data["notifications"]:
            if not isinstance(n, list) or not n or not isinstance(n[0], str):
                raise ValueError("notification")
            notes.append(tuple(n))

        return {
            "_items": items,
            "_lots": lots,
            "_cash": cash,
            "_day": day,
            "_armed": armed,
            "_held": held,
            "_shipped": shipped,
            "_returned": returned,
            "_log": events.EventLog(notes),
