"""Demand simulation (C29).

Customer orders are drawn from the demand ranges in data.toml with a seeded RNG
only, so the same seed always gives the same orders.
"""
import random
import tomllib
from pathlib import Path

_DATA_PATH = Path(__file__).with_name("data.toml")


def _demand_table():
    with open(_DATA_PATH, "rb") as f:
        data = tomllib.load(f)
    table = []
    for sku, spec in data["demand"].items():
        lo, hi = spec["min"], spec["max"]
        if not (isinstance(lo, int) and isinstance(hi, int) and 0 <= lo <= hi):
            raise ValueError(f"bad demand range for {sku}")
        table.append((sku, lo, hi))
    return table


def simulate(days, seed):
    """Return one entry per day; each entry is a list of (sku, qty) customer orders."""
    if isinstance(days, bool) or not isinstance(days, int) or days < 0:
        raise ValueError("days must be a non-negative int")
    rng = random.Random(seed)
    table = _demand_table()
    result = []
    for _ in range(days):
        orders = []
        for sku, lo, hi in table:
            qty = rng.randint(lo, hi)
            if qty > 0:
                orders.append((sku, qty))
        result.append(orders)
    return result
